package br.com.cineo;
import android.app.*;import android.content.*;import android.widget.*;import com.google.android.gms.cast.*;import com.google.android.gms.cast.framework.*;import com.google.android.gms.cast.framework.media.*;import androidx.mediarouter.app.MediaRouteButton;
/** Uses the official default Cast receiver. Only published episodes can be sent. */
class Casting implements SessionManagerListener<CastSession> {
 final MainActivity a;CastContext context;Casting(MainActivity activity){a=activity;}
 void show(){if(!a.drama.active||!a.drama.publicEpisode()){Toast.makeText(a,"Abra um episódio publicado para transmitir.",0).show();return;}try{if(context==null){context=CastContext.getSharedInstance(a);context.getSessionManager().addSessionManagerListener(this,CastSession.class);}LinearLayout page=a.col();page.setPadding(a.dp(20),a.dp(20),a.dp(20),a.dp(20));a.text(page,"Conecte o celular e a TV compatível com Google Cast à mesma rede Wi-Fi. Toque no símbolo para escolher a televisão.",14,MainActivity.MUTED);MediaRouteButton button=new MediaRouteButton(a);button.setContentDescription("Escolher televisão Google Cast");CastButtonFactory.setUpMediaRouteButton(a,button);page.addView(button,new LinearLayout.LayoutParams(a.dp(64),a.dp(64)));CastSession session=context.getSessionManager().getCurrentCastSession();if(session!=null&&session.isConnected()){a.button(page,"Enviar este episódio",MainActivity.RED,()->load(session));a.button(page,"Controles da televisão",MainActivity.CARD,()->a.startActivity(new Intent(a,CineoCastController.class)));a.button(page,"Encerrar transmissão",MainActivity.CARD,()->context.getSessionManager().endCurrentSession(true));}new AlertDialog.Builder(a).setTitle("Assistir na televisão").setView(page).setPositiveButton("Concluir",null).show();}catch(Exception e){new AlertDialog.Builder(a).setTitle("Google Cast indisponível").setMessage("Confira se o Google Play Services está instalado e atualizado neste aparelho.").setPositiveButton("Entendi",null).show();}}
 void load(CastSession session){if(!a.drama.active||!a.drama.publicEpisode())return;final int episode=a.playingEpisode;final int position=a.video==null?0:a.video.getCurrentPosition();a.socialRequest("GET","/shows/"+a.activeShow.optInt("id")+"/episodes",null,r->{org.json.JSONArray eps=r.getJSONArray("items");for(int i=0;i<eps.length();i++){org.json.JSONObject e=eps.getJSONObject(i);if(e.optInt("id")!=episode)continue;MediaMetadata metadata=new MediaMetadata(MediaMetadata.MEDIA_TYPE_TV_SHOW);metadata.putString(MediaMetadata.KEY_TITLE,a.activeShow.optString("title"));metadata.putString(MediaMetadata.KEY_SUBTITLE,a.pro.episodeLabel(e));MediaInfo info=new MediaInfo.Builder(e.optString("url")).setStreamType(MediaInfo.STREAM_TYPE_BUFFERED).setContentType("video/mp4").setMetadata(metadata).build();RemoteMediaClient remote=session.getRemoteMediaClient();if(remote!=null)remote.load(new MediaLoadRequestData.Builder().setMediaInfo(info).setAutoplay(true).setCurrentTime(position).build()).setResultCallback(result->{if(result.getStatus().isSuccess()){if(a.video!=null)a.video.pause();a.startActivity(new Intent(a,CineoCastController.class));}else Toast.makeText(a,"A TV não conseguiu abrir este vídeo.",1).show();});return;}});}
 void release(){if(context!=null)context.getSessionManager().removeSessionManagerListener(this,CastSession.class);}
 public void onSessionStarted(CastSession s,String id){load(s);}public void onSessionResumed(CastSession s,boolean suspended){}public void onSessionEnded(CastSession s,int error){}public void onSessionStarting(CastSession s){}public void onSessionStartFailed(CastSession s,int error){Toast.makeText(a,"Não foi possível conectar à TV.",0).show();}public void onSessionEnding(CastSession s){}public void onSessionResuming(CastSession s,String id){}public void onSessionResumeFailed(CastSession s,int error){}public void onSessionSuspended(CastSession s,int reason){}
}
